class Solution {
    vector<int> getNext(const vector<int>& indices, int n) {
        vector<int> res(n, -1);
        vector<int> st;
        for (int i : indices) {
            while (!st.empty() && st.back() < i) {
                res[st.back()] = i;
                st.pop_back();
            }
            st.push_back(i);
        }
        return res;
    }
